import { sql } from "drizzle-orm";
import {
  boolean,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  smallint,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";
import type { SetTarget } from "./targets.js";

// Conventions (docs/decisions/0009): UUIDv7 ids generated by the client, UTC timestamps,
// soft delete via deleted_at. Same table and column names as the iOS SQLite schema
// (apps/ios/HTSKit/Sources/HTSPersistence/AppDatabase.swift); `pnpm sync:shared` exports
// packages/contracts/db-schema.json and the Swift tests compare both.
const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
  deletedAt: timestamp("deleted_at", { withTimezone: true }),
};

// Root of all user data, so it has no athlete_id of its own.
export const athlete = pgTable("athlete", {
  id: uuid("id").primaryKey(),
  displayName: text("display_name").notNull(),
  defaultRestSeconds: integer("default_rest_seconds").notNull().default(90),
  ...timestamps,
});

const owned = () => ({
  id: uuid("id").primaryKey(),
  athleteId: uuid("athlete_id")
    .notNull()
    .references(() => athlete.id),
});

export const attribute = pgEnum("attribute", [
  "strength",
  "power",
  "conditioning",
  "core",
  "mobility",
]);
export const arcKind = pgEnum("arc_kind", ["normal", "special", "filler"]);
export const arcStatus = pgEnum("arc_status", ["queued", "current", "completed"]);
export const blockKind = pgEnum("block_kind", [
  "activation",
  "strength",
  "combo",
  "chained_combo",
  "fight_round",
  "conditioning",
  "core",
  "mobility",
  "cardio",
]);
export const exerciseUnit = pgEnum("exercise_unit", ["reps", "seconds", "meters", "minutes"]);

/** The year-long cycle (Saga 2026). Holds arcs in order. */
export const saga = pgTable("saga", {
  ...owned(),
  year: smallint("year").notNull(),
  name: text("name").notNull(),
  ...timestamps,
});

/** A phase of the program: N workout templates × weeks. */
export const arc = pgTable(
  "arc",
  {
    ...owned(),
    sagaId: uuid("saga_id")
      .notNull()
      .references(() => saga.id),
    name: text("name").notNull(),
    kanji: text("kanji"),
    /** Name of the coach's real program this arc follows. */
    program: text("program"),
    kind: arcKind("kind").notNull().default("normal"),
    /** Null for filler arcs, which have no duration. */
    weeks: smallint("weeks"),
    /** Local calendar date (no time zone). */
    startDate: date("start_date"),
    status: arcStatus("status").notNull().default("queued"),
    position: integer("position").notNull(),
    /** "Recomeçar contagem": sessions before this instant do not count for the arc. */
    countResetAt: timestamp("count_reset_at", { withTimezone: true }),
    ...timestamps,
  },
  (t) => [
    index("arc_saga_id_idx").on(t.sagaId),
    // Only one current arc per athlete.
    uniqueIndex("arc_one_current_idx")
      .on(t.athleteId)
      .where(sql`${t.status} = 'current' AND ${t.deletedAt} IS NULL`),
  ],
);

/**
 * The recipe of a workout inside an arc (A · Linha de Frente). Reusing it in another arc copies it
 * (docs/decisions/0015); `source_template_id` keeps the origin.
 */
export const workoutTemplate = pgTable(
  "workout_template",
  {
    ...owned(),
    arcId: uuid("arc_id")
      .notNull()
      .references(() => arc.id),
    sourceTemplateId: uuid("source_template_id"),
    letter: text("letter").notNull(),
    name: text("name").notNull(),
    focus: text("focus"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [index("workout_template_arc_id_idx").on(t.arcId)],
);

export const block = pgTable(
  "block",
  {
    ...owned(),
    workoutTemplateId: uuid("workout_template_id")
      .notNull()
      .references(() => workoutTemplate.id),
    kind: blockKind("kind").notNull(),
    /** One or more attributes fed by this block's sets. */
    attributes: jsonb("attributes").$type<(typeof attribute.enumValues)[number][]>().notNull(),
    /** Only for fight rounds (6 to 12 min). */
    durationMinutes: smallint("duration_minutes"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [index("block_workout_template_id_idx").on(t.workoutTemplateId)],
);

/** Exercise catalog, free text with normalized names (docs/decisions/0016). */
export const exercise = pgTable(
  "exercise",
  {
    ...owned(),
    name: text("name").notNull(),
    /** Lowercase, no accents, single spaces: "Barra Fixa" and "barra  fixa" are the same exercise. */
    normalizedName: text("normalized_name").notNull(),
    defaultAttribute: attribute("default_attribute"),
    unit: exerciseUnit("unit").notNull().default("reps"),
    perSide: boolean("per_side").notNull().default(false),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("exercise_athlete_normalized_name_idx")
      .on(t.athleteId, t.normalizedName)
      .where(sql`${t.deletedAt} IS NULL`),
  ],
);

/** An exercise as prescribed inside a block: sets × target, optional own rest. */
export const prescribedExercise = pgTable(
  "prescribed_exercise",
  {
    ...owned(),
    blockId: uuid("block_id")
      .notNull()
      .references(() => block.id),
    exerciseId: uuid("exercise_id")
      .notNull()
      .references(() => exercise.id),
    /** Sets can be a range ("3 a 4"); equal values mean a fixed count. */
    setsMin: smallint("sets_min").notNull(),
    setsMax: smallint("sets_max").notNull(),
    /** One target for every set, or one per set up to sets_max (docs/decisions/0014). */
    targets: jsonb("targets").$type<SetTarget[]>().notNull(),
    restSeconds: integer("rest_seconds"),
    position: integer("position").notNull(),
    ...timestamps,
  },
  (t) => [
    index("prescribed_exercise_block_id_idx").on(t.blockId),
    index("prescribed_exercise_exercise_id_idx").on(t.exerciseId),
  ],
);

export type Athlete = typeof athlete.$inferSelect;
export type NewAthlete = typeof athlete.$inferInsert;
